/**
 * ImportController transition tests (UI-020; the §27 import-side states).
 * Fake ports drive the seams; an event recorder captures screens, states
 * and announcements so the contract is asserted, not the DOM.
 */

import { describe, expect, it } from "vitest";
import {
  ImportController,
  parseProjectFile,
  type ImportEvents,
  type ImportState,
} from "./controller";
import { AudioDecodeError, type DecodedAudio, type ImportPorts } from "./ports";
import type { ScreenState } from "../workspace/screen";
import type {
  AudioFileRef,
  LoadedAudio,
  RecentProjectEntry,
} from "./types";

const DECODED: DecodedAudio = {
  durationSeconds: 12.5,
  sampleRate: 48_000,
  peaks: [0.1, 0.9, 0.3],
};

function projectJson(overrides: Record<string, unknown> = {}): Blob {
  return new Blob([
    JSON.stringify({
      schemaVersion: 1,
      projectId: "proj-1",
      sourceAudio: {
        originalPath: "C:\\audio\\etude.wav",
        contentHash: "hash-etude",
        ...((overrides.sourceAudio as object) ?? {}),
      },
      ...overrides,
    }),
  ]);
}

function makeHarness(portOverrides: Partial<ImportPorts> = {}) {
  const screens: ScreenState[] = [];
  const states: ImportState[] = [];
  const announcements: string[] = [];
  const readyAudios: LoadedAudio[] = [];
  const recents: RecentProjectEntry[][] = [];
  const scoreResults: unknown[] = [];
  const store = new Map<string, Blob>();

  const events: ImportEvents = {
    onScreenChange: (s) => screens.push(s),
    onState: (s) => states.push(s),
    announce: (m) => announcements.push(m),
    onRecentChange: (e) => recents.push([...e]),
    onAudioReady: (a) => readyAudios.push(a),
    onProjectScoreReady: (r) => scoreResults.push(r),
  };

  const ports: ImportPorts = {
    pickAudio: async () => null,
    readAudioBytes: async (path) => {
      const b = store.get(path);
      if (!b) throw new Error(`missing file: ${path}`);
      return b;
    },
    readProjectBytes: async (path) => {
      const b = store.get(path);
      if (!b) throw new Error(`missing project: ${path}`);
      return b;
    },
    decodeAudio: async () => DECODED,
    sha256Hex: async (blob) => {
      const text = await blob.text();
      return `hash-${text}`;
    },
    ...portOverrides,
  };

  const storage = new Map<string, string>();
  const controller = new ImportController(ports, events, {
    getItem: (k) => storage.get(k) ?? null,
    setItem: (k, v) => void storage.set(k, v),
  });

  return {
    controller,
    ports,
    store,
    screens,
    states,
    announcements,
    readyAudios,
    recents,
    scoreResults,
  };
}

const fileRef = (name = "take.wav", content = "bytes"): AudioFileRef => ({
  kind: "file",
  file: new File([content], name),
  name,
});

const pathRef = (path: string, name = path.split("\\").pop() ?? path): AudioFileRef => ({
  kind: "path",
  path,
  name,
});

describe("importRefs — EMPTY → OPENING_AUDIO → AUDIO_READY", () => {
  it("loads a supported file and announces it", async () => {
    const h = makeHarness();
    await h.controller.importRefs([fileRef("take.wav")]);

    expect(h.screens).toEqual(["openingAudio", "audioReady"]);
    const audio = h.readyAudios[0];
    expect(audio.fileName).toBe("take.wav");
    expect(audio.format).toBe("wav");
    expect(audio.durationSeconds).toBe(DECODED.durationSeconds);
    expect(audio.mediaSource.kind).toBe("blob");
    expect(h.controller.getState().phase).toBe("ready");
    expect(h.announcements.at(-1)).toContain("take.wav");
  });

  it("picks the first supported file when several are dropped", async () => {
    const h = makeHarness();
    await h.controller.importRefs([
      fileRef("notes.txt"),
      fileRef("real.flac"),
      fileRef("other.wav"),
    ]);
    expect(h.readyAudios[0]?.fileName).toBe("real.flac");
  });

  it("reads bytes through the port for kind:path refs", async () => {
    const h = makeHarness();
    h.store.set("C:\\audio\\take.wav", new Blob(["wav-bytes"]));
    const calls: string[] = [];
    const ports = {
      ...h.ports,
      readAudioBytes: async (p: string) => {
        calls.push(p);
        return h.store.get(p)!;
      },
    };
    const c = new ImportController(ports, {
      onScreenChange: () => {},
      onState: () => {},
      announce: () => {},
      onRecentChange: () => {},
      onAudioReady: (a) => h.readyAudios.push(a),
    });
    await c.importRefs([pathRef("C:\\audio\\take.wav", "take.wav")]);
    expect(calls).toEqual(["C:\\audio\\take.wav"]);
    expect(h.readyAudios[0]?.sizeBytes).toBe("wav-bytes".length);
  });
});

describe("importRefs — AUDIO_ERROR (§20)", () => {
  it("unsupported extension → error card, 閉じる → EMPTY", async () => {
    const h = makeHarness();
    await h.controller.importRefs([fileRef("memo.txt")]);

    expect(h.screens).toEqual(["audioError"]);
    const s = h.controller.getState();
    expect(s.phase).toBe("error");
    expect(s.issue).toEqual({ kind: "unsupported", fileName: "memo.txt" });
    expect(h.readyAudios).toHaveLength(0);

    h.controller.dismiss();
    expect(h.controller.getState().phase).toBe("idle");
    expect(h.screens.at(-1)).toBe("empty");
  });

  it("decode failure → openFailed, file is only read", async () => {
    const h = makeHarness({
      decodeAudio: async () => {
        throw new AudioDecodeError("cannot decode");
      },
    });
    await h.controller.importRefs([fileRef("corrupt.wav")]);
    expect(h.controller.getState().issue).toEqual({
      kind: "openFailed",
      fileName: "corrupt.wav",
    });
    expect(h.screens.at(-1)).toBe("audioError");
  });

  it("a failed re-import keeps the live workspace and raises an issue", async () => {
    const h = makeHarness();
    await h.controller.importRefs([fileRef("good.wav")]);
    await h.controller.importRefs([fileRef("bad.xyz")]);

    const s = h.controller.getState();
    expect(s.phase).toBe("ready");
    expect(s.audio?.fileName).toBe("good.wav");
    expect(s.issue?.kind).toBe("unsupported");
    // The screen stays audioReady — the issue renders as a dialog.
    expect(h.screens.at(-1)).toBe("audioReady");

    h.controller.dismiss();
    expect(h.controller.getState().issue).toBeNull();
    expect(h.controller.getState().audio?.fileName).toBe("good.wav");
  });
});

describe("openProject — source verification (store.py contract)", () => {
  const entry: RecentProjectEntry = {
    name: "etude",
    path: "C:\\p\\etude.hornscribe.json",
    openedAt: 1,
  };

  it("hash match → AUDIO_READY and the project is touched as recent", async () => {
    const h = makeHarness();
    h.store.set(entry.path, projectJson());
    h.store.set("C:\\audio\\etude.wav", new Blob(["etude"])); // hash-etude

    await h.controller.openProject(entry);

    expect(h.screens).toEqual(["openingAudio", "audioReady"]);
    expect(h.readyAudios[0]?.fileName).toBe("etude.wav");
    expect(h.recents.at(-1)?.[0]?.path).toBe(entry.path);
  });

  it("source file missing → SOURCE_MISSING with relink action", async () => {
    const h = makeHarness();
    h.store.set(entry.path, projectJson());
    // no audio bytes stored → read fails
    await h.controller.openProject(entry);

    expect(h.screens).toEqual(["openingAudio", "sourceMissing"]);
    const s = h.controller.getState();
    expect(s.phase).toBe("sourceMissing");
    expect(s.sourceMissing?.project.sourcePath).toBe("C:\\audio\\etude.wav");
    expect(s.sourceMissing?.mismatch).toBe(false);
  });

  it("hash mismatch at the recorded path → SOURCE_MISSING", async () => {
    const h = makeHarness();
    h.store.set(entry.path, projectJson());
    h.store.set("C:\\audio\\etude.wav", new Blob(["different"]));
    await h.controller.openProject(entry);
    expect(h.controller.getState().phase).toBe("sourceMissing");
  });

  it("corrupt project JSON → projectOpenFailed (not SOURCE_MISSING)", async () => {
    const h = makeHarness();
    h.store.set(entry.path, new Blob(["{corrupt"]));
    await h.controller.openProject(entry);
    const s = h.controller.getState();
    expect(s.phase).toBe("error");
    expect(s.issue).toEqual({
      kind: "projectOpenFailed",
      fileName: "etude",
    });
    expect(h.screens.at(-1)).toBe("audioError");
  });

  it("a dropped .hornscribe.json opens as a project, not an audio error", async () => {
    const h = makeHarness();
    // kind:file ref — the browser-dev/drop path; the recorded source
    // is not on disk so the flow lands on SOURCE_MISSING honestly.
    const file = new File([await projectJson().text()], "etude.hornscribe.json");
    await h.controller.importRefs([{ kind: "file", file, name: file.name }]);
    const s = h.controller.getState();
    expect(s.phase).toBe("sourceMissing");
    expect(s.sourceMissing?.project.name).toBe("etude");
    // No durable path — the project must not enter the recents list.
    expect(h.recents).toHaveLength(0);
  });

  it("saved score extras → onProjectScoreReady restores without re-transcribing (#106)", async () => {
    const h = makeHarness();
    h.store.set(entry.path, projectJson({
      score: { revision: "rev-0123456789abcdef" },
      musicXmlConcert: "<score-partwise/>",
      musicXmlHornF: "<score-partwise/>",
      reviewIssues: [{ id: "ri-000001", reason: "low_model_confidence" }],
    }));
    h.store.set("C:\\audio\\etude.wav", new Blob(["etude"]));

    await h.controller.openProject(entry);

    expect(h.scoreResults).toHaveLength(1);
    const result = h.scoreResults[0] as Record<string, unknown>;
    expect(result.musicXmlConcert).toBe("<score-partwise/>");
    expect(result.scoreRevision).toBe("rev-0123456789abcdef");
    expect(result.reviewIssues).toHaveLength(1);
    expect(h.announcements.at(-1)).toContain("etude");
  });

  it("project without extras → no score event, AUDIO_READY only (#106)", async () => {
    const h = makeHarness();
    h.store.set(entry.path, projectJson());
    h.store.set("C:\\audio\\etude.wav", new Blob(["etude"]));
    await h.controller.openProject(entry);
    expect(h.scoreResults).toHaveLength(0);
    expect(h.screens.at(-1)).toBe("audioReady");
  });

  it("SOURCE_MISSING still restores the score in the background (#106)", async () => {
    const h = makeHarness();
    h.store.set(entry.path, projectJson({
      score: { revision: "rev-0123456789abcdef" },
      musicXmlConcert: "x",
      musicXmlHornF: "y",
    }));
    await h.controller.openProject(entry);
    expect(h.controller.getState().phase).toBe("sourceMissing");
    expect(h.scoreResults).toHaveLength(1);
  });
});

describe("relinkWith — hash-validated relink (store.py relink_source_audio)", () => {
  const entry: RecentProjectEntry = {
    name: "etude",
    path: "C:\\p\\etude.hornscribe.json",
    openedAt: 1,
  };

  async function toSourceMissing(h: ReturnType<typeof makeHarness>) {
    h.store.set(entry.path, projectJson());
    await h.controller.openProject(entry);
    expect(h.controller.getState().phase).toBe("sourceMissing");
  }

  it("matching content → AUDIO_READY + sourceRelinked announce", async () => {
    const h = makeHarness();
    await toSourceMissing(h);
    // Fake sha256Hex is `hash-${text}` — content "etude" matches hash-etude.
    await h.controller.relinkWith(fileRef("etude-copy.wav", "etude"));

    const s = h.controller.getState();
    expect(s.phase).toBe("ready");
    expect(s.audio?.mediaSource.kind).toBe("blob");
    expect(h.screens.at(-1)).toBe("audioReady");
    expect(h.announcements.at(-1)).toContain("関連付け直");
    expect(h.recents.at(-1)?.[0]?.path).toBe(entry.path);
  });

  it("different content → SOURCE_MISSING with mismatch=true", async () => {
    const h = makeHarness();
    await toSourceMissing(h);
    await h.controller.relinkWith(fileRef("nope"));

    const s = h.controller.getState();
    expect(s.phase).toBe("sourceMissing");
    expect(s.sourceMissing?.mismatch).toBe(true);
    expect(h.screens.at(-1)).toBe("sourceMissing");
  });

  it("unreadable candidate keeps SOURCE_MISSING (recovery path stays)", async () => {
    const h = makeHarness();
    await toSourceMissing(h);
    await h.controller.relinkWith(pathRef("C:\\gone\\etude.wav"));

    const s = h.controller.getState();
    expect(s.phase).toBe("sourceMissing");
    expect(s.sourceMissing?.mismatch).toBe(false);
  });
});

describe("serialization guard", () => {
  it("a superseded open cannot overwrite the newer one", async () => {
    let resolveFirst!: (v: DecodedAudio) => void;
    const h = makeHarness({
      decodeAudio: (blob) =>
        blob.size === 5
          ? new Promise<DecodedAudio>((r) => (resolveFirst = r))
          : Promise.resolve(DECODED),
    });

    const first = h.controller.importRefs([fileRef("slow.wav", "12345")]);
    const second = h.controller.importRefs([fileRef("fast.mp3", "12")]);
    await second;
    resolveFirst(DECODED);
    await first;

    const s = h.controller.getState();
    expect(s.audio?.fileName).toBe("fast.mp3");
    expect(h.readyAudios.map((a) => a.fileName)).toEqual(["fast.mp3"]);
  });
});

describe("openViaDialog", () => {
  it("cancel is silent — no state change, no announcement", async () => {
    const h = makeHarness();
    await h.controller.openViaDialog();
    expect(h.states).toHaveLength(0);
    expect(h.screens).toHaveLength(0);
    expect(h.announcements).toHaveLength(0);
  });
});

describe("parseProjectFile", () => {
  const enc = new TextEncoder();
  const parse = (v: unknown) =>
    parseProjectFile(enc.encode(JSON.stringify(v)).buffer as ArrayBuffer, "p");

  it("extracts sourcePath/sourceHash from schema v1", () => {
    const p = parse({
      schemaVersion: 1,
      projectId: "x",
      sourceAudio: { originalPath: "/a.wav", contentHash: "h" },
    });
    expect(p).toMatchObject({
      projectId: "x",
      sourcePath: "/a.wav",
      sourceHash: "h",
    });
  });

  it("throws on wrong schemaVersion / missing projectId / non-object", () => {
    expect(() => parse({ schemaVersion: 2, projectId: "x" })).toThrow();
    expect(() => parse({ schemaVersion: 1 })).toThrow();
    expect(() => parse([1, 2])).toThrow();
  });

  it("tolerates a missing sourceAudio (null source fields)", () => {
    const p = parse({ schemaVersion: 1, projectId: "x", sourceAudio: null });
    expect(p.sourcePath).toBeNull();
    expect(p.sourceHash).toBeNull();
  });

  it("reassembles scoreResult from saved extras (#106)", () => {
    const p = parse({
      schemaVersion: 1,
      projectId: "x",
      sourceAudio: null,
      score: { revision: "rev-0123456789abcdef" },
      musicXmlConcert: "<a/>",
      musicXmlHornF: "<b/>",
      reviewIssues: [{ id: "ri-1" }],
      scoreDocument: { parts: [] },
      meta: { tempoBpm: 120 },
    });
    const result = p.scoreResult as Record<string, unknown>;
    expect(result).toMatchObject({
      musicXmlConcert: "<a/>",
      musicXmlHornF: "<b/>",
      scoreRevision: "rev-0123456789abcdef",
    });
    expect(result.reviewIssues).toHaveLength(1);
    expect(result.scoreDocument).toEqual({ parts: [] });
  });

  it("no MusicXML extras → scoreResult is null (#106)", () => {
    const p = parse({ schemaVersion: 1, projectId: "x", sourceAudio: null });
    expect(p.scoreResult).toBeNull();
  });
});

/**
 * Import flow controller (UI-020 / issue #25; docs/GUI_UX_SPEC.md §3/§4/§20).
 *
 * Framework-free: App subscribes to state + screen events; tests drive it
 * with fake ports. The controller owns the §27 import-side transitions —
 *
 *   EMPTY ─pick/drop→ OPENING_AUDIO ─ok→ AUDIO_READY
 *                         ├─ unsupported/corrupt → AUDIO_ERROR ─閉じる→ EMPTY
 *                         └─ (audio already loaded: error surfaces as a
 *                             dialog issue over the kept workspace)
 *   recent project ─→ OPENING_AUDIO ─source ok→ AUDIO_READY
 *                         └─ path/hash failure → SOURCE_MISSING
 *                                └─ 音源を指定 → hash ok → AUDIO_READY
 *                                                mismatch → SOURCE_MISSING
 *
 * Error policy (§20): state what failed, what is kept, the next action —
 * a failed re-import never destroys a loaded audio session, and the source
 * file is only ever read (FND-001: identity = content hash, not location).
 */
import type { ScreenState } from "../workspace/screen";
import { ja } from "../strings/ja";
import { type ImportPorts } from "./ports";
import {
  audioFormatOf,
  baseName,
  projectDisplayName,
} from "./formats";
import {
  recordRecentProject,
  loadRecentProjects,
} from "./recentProjects";
import type {
  AudioFileRef,
  AudioFormat,
  ImportIssue,
  LoadedAudio,
  ProjectSummary,
  RecentProjectEntry,
  RecordedAudioRef,
  SourceMissingInfo,
} from "./types";

export type ImportPhase =
  | "idle"
  | "opening"
  | "ready"
  | "error"
  | "sourceMissing";

export interface ImportState {
  readonly phase: ImportPhase;
  /** File/project name shown while `phase === "opening"`. */
  readonly openingLabel: string | null;
  /** "audio" | "project" selects the loading copy variant. */
  readonly openingKind: "audio" | "project" | null;
  readonly audio: LoadedAudio | null;
  /** Recoverable failure — card content on AUDIO_ERROR, dialog content
      when the workspace already has audio (the error never destroys it). */
  readonly issue: ImportIssue | null;
  readonly sourceMissing: SourceMissingInfo | null;
}

export const INITIAL_IMPORT_STATE: ImportState = {
  phase: "idle",
  openingLabel: null,
  openingKind: null,
  audio: null,
  issue: null,
  sourceMissing: null,
};

export interface ImportEvents {
  /** Screen transitions owned by the import flow (§27). */
  onScreenChange(screen: ScreenState): void;
  /** Mirrors state for React consumers. */
  onState(state: ImportState): void;
  /** aria-live status bar announcements (role="status"). */
  announce(message: string): void;
  /** Recent-projects list changed (persisted + UI). */
  onRecentChange(entries: readonly RecentProjectEntry[]): void;
  /** Decoded audio is ready — host wires it into the transport adapter. */
  onAudioReady(audio: LoadedAudio): void;
  /** Optional (#106): the opened project carried a saved score — the
   *  host restores it and jumps to SCORE_READY instead of waiting for
   *  a re-transcription. Fires after the usual state/screen updates. */
  onProjectScoreReady?(result: unknown): void;
}

type RecentStorage = Pick<Storage, "getItem" | "setItem"> | null;

export class ImportController {
  private state: ImportState = INITIAL_IMPORT_STATE;
  /** Serialization guard: a superseded open (user re-picked mid-load) must
      not overwrite newer state when it resolves late. */
  private generation = 0;

  constructor(
    private readonly ports: ImportPorts,
    private readonly events: ImportEvents,
    private readonly storage: RecentStorage = null,
  ) {}

  getState(): ImportState {
    return this.state;
  }

  /** `file.openAudio` (Ctrl+O / 開く / drop fallback): pick then import. */
  async openViaDialog(): Promise<void> {
    let ref: AudioFileRef | null;
    try {
      ref = await this.ports.pickAudio();
    } catch {
      // A picker failure is not a file error — surface the generic
      // open-failure issue rather than an unhandled rejection.
      this.fail({ kind: "openFailed" });
      return;
    }
    if (!ref) return; // cancel is silent — not an error
    await this.importRefs([ref]);
  }

  /**
   * Drag&drop / dialog entry point. With several files the first supported
   * one wins (single-document app); zero supported → honest format error.
   */
  async importRefs(refs: readonly AudioFileRef[]): Promise<void> {
    if (refs.length === 0) return;
    // A dropped/picked .hornscribe.json is a project open, not an audio
    // import — the dialog's "all files" escape hatch can hand one over.
    const projRef = refs.find((r) => r.name.endsWith(".hornscribe.json"));
    if (projRef) {
      const bytes =
        projRef.kind === "file" ? projRef.file : undefined;
      await this.openProject(
        {
          name: projectDisplayName(projRef.name),
          path: projRef.kind === "path" ? projRef.path : "",
          openedAt: Date.now(),
        },
        bytes,
      );
      return;
    }
    const ref = refs.find((r) => audioFormatOf(r.name) !== null) ?? refs[0];
    const format = audioFormatOf(ref.name);
    if (format === null) {
      this.fail({ kind: "unsupported", fileName: ref.name });
      return;
    }
    await this.importAudioRef(ref, format);
  }

  /**
   * FEAT-001 (#60): 録音バッファを直接取り込む(PC音源/マイク録音)。
   * `ref` は `kind:"recording"` で、`blob` は WAV または MediaRecorder
   * 出力(ブラウザ dev)。拡張子は常に `.wav`/`.webm` を仮定するため
   * `audioFormatOf` の allowlist を迂回して良い(録音由来なので形式は
   * 自明)。失敗時は openFailed に落とす。
   */
  async importRecording(ref: RecordedAudioRef): Promise<void> {
    const gen = this.begin("audio", ref.name);
    try {
      // Tauri 録音は保存済みファイルを読む(#70: 実ファイル=リリンク可能)。
      const blob = ref.blob ?? (await this.ports.readAudioBytes(ref.path!));
      const contentHash = ref.path
        ? await this.ports.sha256Hex(blob)
        : undefined;
      const decoded = await this.ports.decodeAudio(blob, ref.name);
      if (!this.isCurrent(gen)) return;
      const audio: LoadedAudio = {
        ref: { ...ref, contentHash },
        fileName: ref.name,
        // 録音物は decode 可能なコンテナなので拡張子は実質 wav。
        format: "wav",
        sizeBytes: blob.size,
        durationSeconds: decoded.durationSeconds,
        sampleRate: decoded.sampleRate,
        peaks: decoded.peaks,
        mediaSource: { kind: "blob", blob },
      };
      this.setState({
        phase: "ready",
        openingLabel: null,
        openingKind: null,
        audio,
        issue: null,
        sourceMissing: null,
      });
      this.events.onAudioReady(audio);
      this.events.announce(
        ref.source === "loopback"
          ? `PCの音を取り込みました(${ref.name})`
          : `録音を取り込みました(${ref.name})`,
      );
    } catch {
      if (!this.isCurrent(gen)) return;
      this.fail({ kind: "openFailed", fileName: ref.name });
    }
  }

  /** OPENING_AUDIO → AUDIO_READY, or AUDIO_ERROR. */
  private async importAudioRef(
    ref: AudioFileRef,
    format: AudioFormat,
  ): Promise<void> {
    const gen = this.begin("audio", ref.name);
    try {
      const blob = await this.blobFor(ref);
      const decoded = await this.ports.decodeAudio(blob, ref.name);
      if (!this.isCurrent(gen)) return;
      const audio: LoadedAudio = {
        ref,
        fileName: ref.name,
        format,
        sizeBytes: blob.size,
        durationSeconds: decoded.durationSeconds,
        sampleRate: decoded.sampleRate,
        peaks: decoded.peaks,
        mediaSource: { kind: "blob", blob },
      };
      this.setState({
        phase: "ready",
        openingLabel: null,
        openingKind: null,
        audio,
        issue: null,
        sourceMissing: null,
      });
      this.events.onAudioReady(audio);
      this.events.announce(ja.import.feedback.loaded(ref.name));
    } catch {
      if (!this.isCurrent(gen)) return;
      this.fail({ kind: "openFailed", fileName: ref.name });
    }
  }

  /**
   * 最近使ったプロジェクト → verify the recorded source path (store.py
   * `verify_source_audio`: exists + content hash) → AUDIO_READY, else
   * SOURCE_MISSING with the relink action.
   * `bytes` carries a browser-dev File ref (no durable path — the
   * project is opened but not recorded in the recents list).
   */
  async openProject(
    entry: RecentProjectEntry,
    bytes?: Blob,
  ): Promise<void> {
    const gen = this.begin("project", entry.name);
    try {
      const blob = bytes ?? (await this.ports.readProjectBytes(entry.path));
      // Browser-dev File refs have no durable path — project.path
      // stays "" so touchRecent skips them; the display name comes
      // from the file name instead.
      const project = parseProjectFile(
        await blob.arrayBuffer(),
        entry.path,
        entry.path ? undefined : entry.name,
      );
      if (!this.isCurrent(gen)) return;
      if (!project.sourcePath || !project.sourceHash) {
        this.enterSourceMissing(project, false);
        return;
      }
      let audioBlob: Blob;
      try {
        audioBlob = await this.ports.readAudioBytes(project.sourcePath);
      } catch {
        if (!this.isCurrent(gen)) return;
        this.enterSourceMissing(project, false);
        return;
      }
      const hash = await this.ports.sha256Hex(audioBlob);
      if (!this.isCurrent(gen)) return;
      if (hash !== project.sourceHash) {
        // File at the recorded path exists but content differs —
        // store.py treats this like a moved source (verify fails).
        this.enterSourceMissing(project, false);
        return;
      }
      try {
        const decoded = await this.ports.decodeAudio(audioBlob, entry.name);
        if (!this.isCurrent(gen)) return;
        this.finishProjectOpen(
          project,
          {
            kind: "path",
            path: project.sourcePath,
            name: baseName(project.sourcePath),
          },
          audioBlob,
          decoded,
        );
      } catch {
        if (!this.isCurrent(gen)) return;
        this.fail({
          kind: "openFailed",
          fileName: baseName(project.sourcePath),
        });
      }
    } catch {
      if (!this.isCurrent(gen)) return;
      this.fail({ kind: "projectOpenFailed", fileName: entry.name });
    }
  }

  /** SOURCE_MISSING: 「音源を指定」 — pick a candidate then verify. */
  async pickRelinkSource(): Promise<void> {
    let ref: AudioFileRef | null;
    try {
      ref = await this.ports.pickAudio();
    } catch {
      // Picker failure while relinking — stay on the SOURCE_MISSING card
      // and say what happened; the user can retry 音源を指定.
      this.events.announce(ja.import.errors.openFailedBody);
      return;
    }
    if (!ref) return;
    await this.relinkWith(ref);
  }

  /**
   * Hash-based relink, the same contract as
   * `ProjectStore.relink_source_audio`: the candidate must hash to the
   * recorded content hash — identity is content, not location.
   */
  async relinkWith(ref: AudioFileRef): Promise<void> {
    const sm = this.state.sourceMissing;
    if (!sm) return;
    const gen = this.begin("project", sm.project.name);
    try {
      const blob = await this.blobFor(ref);
      const hash = await this.ports.sha256Hex(blob);
      if (!this.isCurrent(gen)) return;
      if (hash !== sm.project.sourceHash) {
        this.enterSourceMissing(sm.project, true);
        return;
      }
      const decoded = await this.ports.decodeAudio(blob, ref.name);
      if (!this.isCurrent(gen)) return;
      const format = audioFormatOf(ref.name) ?? "wav";
      const audio: LoadedAudio = {
        ref,
        fileName: ref.name,
        format,
        sizeBytes: blob.size,
        durationSeconds: decoded.durationSeconds,
        sampleRate: decoded.sampleRate,
        peaks: decoded.peaks,
        mediaSource: { kind: "blob", blob },
      };
      this.setState({
        phase: "ready",
        openingLabel: null,
        openingKind: null,
        audio,
        issue: null,
        sourceMissing: null,
      });
      this.touchRecent(sm.project);
      this.events.onAudioReady(audio);
      // #106: the project's saved score (already restored in the
      // background) can now land — the relinked audio matches the
      // recorded content hash.
      if (sm.project.scoreResult != null) {
        this.events.onProjectScoreReady?.(sm.project.scoreResult);
        this.events.announce(ja.import.feedback.projectOpened(sm.project.name));
      } else {
        this.events.announce(ja.import.feedback.sourceRelinked);
      }
    } catch {
      if (!this.isCurrent(gen)) return;
      // Candidate unreadable or undecodable after a hash match — stay on
      // the missing-source card; the status line carries what happened
      // (the card itself already offers the retry action).
      this.enterSourceMissing(sm.project, false);
      this.events.announce(ja.import.errors.openFailedBody);
    }
  }

  /** 閉じる on AUDIO_ERROR / SOURCE_MISSING → EMPTY; on a kept workspace
      (issue dialog over audio) it only clears the issue. */
  dismiss(): void {
    if (this.state.phase === "error" || this.state.phase === "sourceMissing") {
      this.setState({ ...INITIAL_IMPORT_STATE });
      return;
    }
    if (this.state.issue) {
      this.setState({ ...this.state, issue: null });
    }
  }

  /** Recent entries (host renders them in the EMPTY state). */
  recentProjects(): RecentProjectEntry[] {
    return loadRecentProjects(this.storage);
  }

  /* ----------------------------- internals ----------------------------- */

  private begin(kind: "audio" | "project", label: string): number {
    const gen = ++this.generation;
    this.setState({
      phase: "opening",
      openingLabel: label,
      openingKind: kind,
      audio: this.state.audio,
      issue: null,
      sourceMissing: null,
    });
    return gen;
  }

  private isCurrent(gen: number): boolean {
    return gen === this.generation;
  }

  private fail(issue: ImportIssue): void {
    if (this.state.audio) {
      // Workspace is alive — the issue becomes a dialog over it, the
      // loaded audio/waveform/transport all stay (§20 "what is kept").
      this.setState({ ...this.state, phase: "ready", issue });
    } else {
      this.setState({
        phase: "error",
        openingLabel: null,
        openingKind: null,
        audio: null,
        issue,
        sourceMissing: null,
      });
    }
  }

  private enterSourceMissing(
    project: ProjectSummary,
    mismatch: boolean,
  ): void {
    this.setState({
      phase: "sourceMissing",
      openingLabel: null,
      openingKind: null,
      audio: null,
      issue: null,
      sourceMissing: { project, mismatch },
    });
    // #106: the score survives a missing/moved source — restore it
    // now; the audio can be relinked afterwards.
    if (project.scoreResult != null) {
      this.events.onProjectScoreReady?.(project.scoreResult);
    }
  }

  private finishProjectOpen(
    project: ProjectSummary,
    ref: AudioFileRef,
    blob: Blob,
    decoded: { durationSeconds: number; sampleRate: number; peaks: readonly number[] },
  ): void {
    const format = audioFormatOf(ref.name) ?? "wav";
    const audio: LoadedAudio = {
      ref,
      fileName: ref.name,
      format,
      sizeBytes: blob.size,
      durationSeconds: decoded.durationSeconds,
      sampleRate: decoded.sampleRate,
      peaks: decoded.peaks,
      mediaSource: { kind: "blob", blob },
    };
    this.setState({
      phase: "ready",
      openingLabel: null,
      openingKind: null,
      audio,
      issue: null,
      sourceMissing: null,
    });
    this.touchRecent(project);
    this.events.onAudioReady(audio);
    // #106: a project saved with score extras skips re-transcription —
    // the host restores the document and lands on SCORE_READY.
    if (project.scoreResult != null) {
      this.events.onProjectScoreReady?.(project.scoreResult);
      this.events.announce(ja.import.feedback.projectOpened(project.name));
    } else {
      this.events.announce(ja.import.feedback.loaded(ref.name));
    }
  }

  private touchRecent(project: ProjectSummary): void {
    // A project opened from browser bytes has no durable path — the
    // recents list only records entries that can actually be reopened.
    if (!project.path) return;
    const list = recordRecentProject(
      { name: project.name, path: project.path },
      this.storage,
    );
    this.events.onRecentChange(list);
  }

  private async blobFor(ref: AudioFileRef): Promise<Blob> {
    return ref.kind === "file" ? ref.file : this.ports.readAudioBytes(ref.path);
  }

  private setState(next: ImportState): void {
    this.state = next;
    this.events.onState(next);
    const screen = screenForPhase(next.phase);
    if (screen) this.events.onScreenChange(screen);
  }
}

/** The screen states the import flow drives; "ready" is the last one it
    owns — later transitions belong to the transcription/score features. */
function screenForPhase(phase: ImportPhase): ScreenState | null {
  switch (phase) {
    case "idle":
      return "empty";
    case "opening":
      return "openingAudio";
    case "ready":
      return "audioReady";
    case "error":
      return "audioError";
    case "sourceMissing":
      return "sourceMissing";
  }
}

/* --------------------------- project parsing --------------------------- */

/**
 * Parse a `.hornscribe.json` document into the relink-relevant summary
 * (schema v1 — mirrors `HornScribeProject.from_dict`). Throws on malformed
 * or unsupported documents → caller maps to `projectOpenFailed`.
 */
export function parseProjectFile(
  bytes: ArrayBuffer,
  path: string,
  displayName?: string,
): ProjectSummary {
  const data = JSON.parse(new TextDecoder().decode(bytes)) as Record<
    string,
    unknown
  >;
  if (typeof data !== "object" || data === null) {
    throw new Error("project document is not an object");
  }
  if (data.schemaVersion !== 1) {
    throw new Error(`unsupported schemaVersion: ${String(data.schemaVersion)}`);
  }
  if (typeof data.projectId !== "string" || data.projectId === "") {
    throw new Error("projectId is missing or malformed");
  }
  const source = data.sourceAudio as Record<string, unknown> | null;
  return {
    path,
    projectId: data.projectId,
    name: displayName ?? projectDisplayName(path),
    sourcePath:
      source && typeof source.originalPath === "string"
        ? source.originalPath
        : null,
    sourceHash:
      source && typeof source.contentHash === "string"
        ? source.contentHash
        : null,
    scoreResult: scoreResultFromProject(data),
  };
}

/**
 * Reassemble the completed-job `result` shape from the project's saved
 * extras (#106). `engineDocumentFromResult` and `scoreHandoffFromResult`
 * consume this directly — the score is restored without re-transcribing.
 * Returns null when the file carries no MusicXML (externally authored
 * projects keep the AUDIO_READY-only open path).
 */
function scoreResultFromProject(
  data: Record<string, unknown>,
): Record<string, unknown> | null {
  const concert = data.musicXmlConcert;
  const horn = data.musicXmlHornF;
  if (typeof concert !== "string" || typeof horn !== "string") {
    return null;
  }
  const score = data.score as Record<string, unknown> | null;
  return {
    musicXmlConcert: concert,
    musicXmlHornF: horn,
    scoreRevision:
      score && typeof score.revision === "string" ? score.revision : "rev-project",
    reviewIssues: Array.isArray(data.reviewIssues) ? data.reviewIssues : [],
    scoreDocument: data.scoreDocument ?? null,
    meta: data.meta ?? {},
  };
}

/**
 * Production ImportPorts (UI-020).
 *
 * Environment matrix:
 * - Tauri webview: native open dialog via @tauri-apps/plugin-dialog
 *   (capability `dialog:allow-open` — the only plugin grant; no fs/asset
 *   protocol), file bytes via the self-limited `read_audio_bytes` /
 *   `read_project_file` commands (extension allowlist + size cap in Rust).
 * - Plain-browser dev (`vite dev`): `<input type=file>` picker and
 *   File-object drops — bytes come straight from the File, and the
 *   path-only ports throw (they are unreachable in that mode anyway).
 *
 * Every port degrades instead of throwing where a fallback exists, so the
 * shell keeps rendering in a bare browser session.
 */
import { invoke } from "@tauri-apps/api/core";
import { open as openDialog } from "@tauri-apps/plugin-dialog";
import { ja } from "../strings/ja";
import { AUDIO_EXTENSIONS, baseName } from "./formats";
import {
  AudioDecodeError,
  type DecodedAudio,
  type ImportPorts,
} from "./ports";
import type { AudioFileRef } from "./types";

/** True inside the Tauri webview (the IPC bridge is injected). */
function isTauri(): boolean {
  return (
    typeof window !== "undefined" && "__TAURI_INTERNALS__" in window
  );
}

/* ------------------------------ file picker ------------------------------ */

async function pickViaDialog(): Promise<AudioFileRef | null> {
  const selected = await openDialog({
    multiple: false,
    directory: false,
    filters: [
      {
        name: ja.import.dialog.audioFilter,
        extensions: [...AUDIO_EXTENSIONS],
      },
      {
        // .hornscribe.json opens as a project (importRefs routes it).
        name: ja.import.dialog.projectFilter,
        extensions: ["json"],
      },
      // An escape hatch so the "unsupported format" recovery path stays
      // reachable through the dialog, not only through drag&drop.
      { name: ja.import.dialog.allFiles, extensions: ["*"] },
    ],
  });
  if (typeof selected !== "string" || selected === "") return null;
  return { kind: "path", path: selected, name: baseName(selected) };
}

/**
 * Browser-dev fallback picker. `cancel` is observable on Chrome-family
 * browsers; the window-focus timer covers engines without the event.
 */
function pickViaFileInput(): Promise<AudioFileRef | null> {
  return new Promise((resolve) => {
    const input = document.createElement("input");
    input.type = "file";
    input.accept =
      AUDIO_EXTENSIONS.map((e) => `.${e}`).join(",") + ",.json";
    let settled = false;
    const done = (ref: AudioFileRef | null) => {
      if (settled) return;
      settled = true;
      resolve(ref);
    };
    input.addEventListener("change", () => {
      const file = input.files?.[0] ?? null;
      done(file ? { kind: "file", file, name: file.name } : null);
    });
    input.addEventListener("cancel", () => done(null));
    // Focus returning without a change event ≈ cancel (Safari/older engines).
    const onFocus = () => setTimeout(() => done(null), 400);
    window.addEventListener("focus", onFocus, { once: true });
    input.click();
  });
}

/* ------------------------------- raw bytes ------------------------------- */

/** Tauri returns binary IPC payloads as ArrayBuffer/Uint8Array; the JSON
 *  fallback is a number[] — normalize all three into a fresh
 *  `Uint8Array<ArrayBuffer>` (a view over a SharedArrayBuffer is not a
 *  valid BlobPart under the typed-array generics). */
function toUint8(data: unknown): Uint8Array<ArrayBuffer> {
  if (data instanceof ArrayBuffer) return new Uint8Array(data);
  if (ArrayBuffer.isView(data)) {
    // Copy: `data.buffer` is ArrayBufferLike — copying guarantees a plain
    // ArrayBuffer for the Blob constructor.
    return new Uint8Array(
      new Uint8Array(data.buffer, data.byteOffset, data.byteLength),
    );
  }
  if (Array.isArray(data)) return new Uint8Array(data as number[]);
  throw new Error("unexpected binary IPC payload");
}

async function invokeBytes(command: string, path: string): Promise<Blob> {
  const raw = await invoke<unknown>(command, { path });
  return new Blob([toUint8(raw)]);
}

/* ------------------------------- decoding -------------------------------- */

const PEAK_BUCKETS = 600;

let sharedAudioContext: AudioContext | null = null;

/** Merge all channels into |peak| buckets for the waveform strip. */
export function computePeaks(buffer: AudioBuffer, buckets = PEAK_BUCKETS): number[] {
  const length = buffer.length;
  const channels = buffer.numberOfChannels;
  const peaks = new Array<number>(buckets).fill(0);
  if (length === 0 || channels === 0) return peaks;
  const per = Math.max(1, Math.floor(length / buckets));
  for (let c = 0; c < channels; c++) {
    const data = buffer.getChannelData(c);
    for (let b = 0; b < buckets; b++) {
      const start = b * per;
      const end = Math.min(start + per, length);
      let peak = peaks[b];
      for (let i = start; i < end; i++) {
        const v = Math.abs(data[i]);
        if (v > peak) peak = v;
      }
      peaks[b] = peak;
    }
  }
  return peaks;
}

async function decodeWithWebAudio(blob: Blob): Promise<DecodedAudio> {
  const Ctor: typeof AudioContext | undefined =
    globalThis.AudioContext ??
    (globalThis as { webkitAudioContext?: typeof AudioContext })
      .webkitAudioContext;
  if (!Ctor) {
    // Headless/test environments — decoding is unavailable, not "bad file".
    throw new AudioDecodeError("AudioContext unavailable");
  }
  sharedAudioContext ??= new Ctor();
  const raw = await blob.arrayBuffer();
  let buffer: AudioBuffer;
  try {
    buffer = await sharedAudioContext.decodeAudioData(raw);
  } catch (e) {
    throw new AudioDecodeError(
      e instanceof Error ? e.message : "decodeAudioData failed",
    );
  }
  return {
    durationSeconds: buffer.duration,
    sampleRate: buffer.sampleRate,
    peaks: computePeaks(buffer),
  };
}

async function sha256Hex(blob: Blob): Promise<string> {
  const digest = await crypto.subtle.digest(
    "SHA-256",
    await blob.arrayBuffer(),
  );
  return [...new Uint8Array(digest)]
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

/* ------------------------------ composition ------------------------------ */

export function createImportPorts(): ImportPorts {
  return {
    pickAudio: () => (isTauri() ? pickViaDialog() : pickViaFileInput()),
    readAudioBytes: (path) => invokeBytes("read_audio_bytes", path),
    readProjectBytes: (path) => invokeBytes("read_project_file", path),
    decodeAudio: (blob) => decodeWithWebAudio(blob),
    sha256Hex,
  };
}
